// Game: Quake
// Format: Valve
// Showcase Map - Demonstrates all engine features

// ==================== WORLDSPAWN ====================
{
"classname" "worldspawn"
"message" "Feature Showcase Map"
"camera_mode" "fake_ortho"
"camera_height" "400"
// Floor plane (1600x1600)
{
( -800 -800 -16 ) ( 800 800 -16 ) ( -800 800 -16 ) color_80_80_80 0 0 0 1 1
( -800 -800 -32 ) ( -800 800 -32 ) ( 800 800 -32 ) color_40_40_40 0 0 0 1 1
( -800 -800 -16 ) ( -800 -800 -32 ) ( 800 -800 -16 ) color_60_60_60 0 0 0 1 1
( -800 800 -16 ) ( 800 800 -16 ) ( -800 800 -32 ) color_60_60_60 0 0 0 1 1
( -800 800 -16 ) ( -800 800 -32 ) ( -800 -800 -16 ) color_60_60_60 0 0 0 1 1
( 800 800 -16 ) ( 800 -800 -16 ) ( 800 800 -32 ) color_60_60_60 0 0 0 1 1
}
}

